# PlatformIO pre-build script: what core embeds in a build, generated by
# core's own tools into the build directory and compiled, so the firmware and
# hub-sim embed the same bytes. Each generator leaves an unchanged file alone,
# so nothing recompiles. Nothing generated lands in git.
#   - the built-in device profiles (profiles/*.json, core/tools/embed_profiles.py):
#     hubbo::config::kBuiltinProfileFiles, read by core's builtinProfiles();
#   - the agent docs (api/openapi.yaml as JSON, docs/api.md, docs/llms.txt;
#     core/tools/embed_docs.py, needs PyYAML): hubbo::api::docs::kOpenApiJson
#     kAgentGuide and kLlmsTxt (hubbo/api/agent_docs.h), raw and gzipped.
import os
import subprocess
import sys

Import("env")  # noqa: F821  (SCons)

PROJECT = env.subst("$PROJECT_DIR")  # noqa: F821
REPO = os.path.normpath(os.path.join(PROJECT, ".."))
BUILD = env.subst("$BUILD_DIR")  # noqa: F821
TOOLS = os.path.join(REPO, "core", "tools")

# Built here, before the library finder adds core's headers (and its vendored
# ArduinoJson, which core/library.json adds for core only) for our sources.
env.Append(CPPPATH=[os.path.join(REPO, "core", "include"),  # noqa: F821
                    os.path.join(REPO, "core", "third_party", "ArduinoJson")])


def embed(name, tool, inputs, output):
    gen_dir = os.path.join(BUILD, name + "_gen")
    os.makedirs(gen_dir, exist_ok=True)
    args = [sys.executable, os.path.join(TOOLS, tool)] + [os.path.join(REPO, i) for i in inputs]
    if subprocess.call(args + [os.path.join(gen_dir, output)]) != 0:
        sys.stderr.write("\n*** %s: %s failed\n\n" % (name, tool))
        env.Exit(1)  # noqa: F821
    env.BuildSources(os.path.join("$BUILD_DIR", name + "_obj"), gen_dir)  # noqa: F821


embed("profiles", "embed_profiles.py", ["profiles"], "builtin_profiles.cpp")
embed("docs", "embed_docs.py", ["api/openapi.yaml", "docs/api.md", "docs/llms.txt"], "agent_docs.cpp")
